<?php $viewMode=($_GET['mode']??'')==='view'; ?><main class="content"><div class="page-actions"><a href="<?=url('/admin/catalogos')?>">← Volver a catálogos</a><?php if($viewMode&&$record):?><a class="primary" href="<?=url('/admin/catalogos/formulario?type='.$type.'&id='.$record['id'])?>">Editar registro</a><?php endif;?></div><section class="panel form-page narrow"><div class="panel-head"><div><span class="eyebrow">CATÁLOGO DEL SISTEMA</span><h2><?=$viewMode?'Detalle':($record?'Editar':'Nuevo')?> <?=e(strtolower($label))?></h2><p><?=$viewMode?'Consulta la información del registro.':'Define el nombre que se mostrará en formularios y módulos.'?></p></div></div><?php if($viewMode):?><div class="detail-grid single"><div><small>Identificador</small><b>#<?=$record['id']?></b></div><div><small>Nombre</small><b><?=e($record['name'])?></b></div><?php if($type==='tabulator_subgroups'):?><div><small>Grupo relacionado</small><b>#<?=e($record['group_id'])?></b></div><?php endif;?></div><?php else:?><form method="post" action="<?=url('/admin/catalogos/guardar')?>"><?=csrf_field()?><input type="hidden" name="type" value="<?=$type?>"><input type="hidden" name="id" value="<?=e($record['id']??'')?>"><div class="form-grid one"><label>Nombre<input required name="name" value="<?=e($record['name']??'')?>" autofocus></label><?php if($type==='tabulator_subgroups'):?><label>Grupo de tabuladores<select name="group_id" required><?php foreach($groups as $g):?><option value="<?=$g['id']?>" <?=($record['group_id']??null)==$g['id']?'selected':''?>><?=e($g['name'])?></option><?php endforeach;?></select></label><?php endif;?></div><div class="form-actions"><a class="secondary" href="<?=url('/admin/catalogos')?>">Cancelar</a><button class="primary">Guardar registro</button></div></form><?php endif;?></section></main>
